import { test } from "node:test";
import assert from "node:assert/strict";
import { wifiDiscovery } from "../web/wifi.js";

// Minimal controls retain text separately from values, as native options do in the browser.
function controls(t) {
	const elements = new Map();
	const $ = (id) => {
		if (!elements.has(id)) elements.set(id, {
			value: "", hidden: true, disabled: false, options: [],
			replaceChildren(...options) { this.options = options; },
			add(option) { this.options.push(option); },
			focus() { this.focused = true; },
		});
		return elements.get(id);
	};
	const original = globalThis.Option;
	globalThis.Option = class { constructor(text, value) { this.text = text; this.value = value; } };
	t.after(() => { if (original) globalThis.Option = original; else delete globalThis.Option; });
	return $;
}

test("settings discovers networks, sorts and deduplicates them, and fills the selected SSID", async (t) => {
	const $ = controls(t);
	const ssid = '<img src=x onerror="x">';
	t.mock.method(globalThis, "fetch", async (url, options) => {
		assert.equal(url, "/json/net");
		assert.equal(options.cache, "no-store");
		return { ok: true, json: async () => ({ networks: [
			{ ssid: "Home", rssi: -80 }, { ssid, rssi: -50 }, { ssid: "Home", rssi: -30 },
			{ ssid: "", rssi: -20 }, { ssid: "x".repeat(33), rssi: -20 }, { ssid: "Invalid", rssi: "bad" },
		] }) };
	});
	const wifi = wifiDiscovery($);
	assert.equal($("wifiDiscovery").hidden, false);
	await wifi.open();
	assert.deepEqual($("wifiNetworks").options.map((option) => option.value), ["", "Home", ssid]);
	assert.equal($("wifiNetworks").options[2].text, ssid + " (-50 dBm)");
	assert.equal($("wifiNetworkLabel").hidden, false);
	$("wifiPassword").value = "previous password";
	$("wifiNetworks").value = "Home";
	$("wifiNetworks").onchange();
	assert.equal($("ssid").value, "Home");
	assert.equal($("wifiPassword").value, "");
	assert.equal($("wifiPassword").focused, true);
	await wifi.open();
	assert.equal(globalThis.fetch.mock.callCount(), 1);
	$("ssid").oninput();
	assert.equal($("wifiNetworks").value, "");
});

test("pending scans are polled without clearing manually entered credentials", async (t) => {
	const $ = controls(t);
	let calls = 0;
	t.mock.method(globalThis, "setTimeout", (callback) => { queueMicrotask(callback); return 0; });
	t.mock.method(globalThis, "fetch", async () => ({ ok: true, json: async () => ({ networks: ++calls < 3 ? [] : [{ ssid: "Home", rssi: -40 }] }) }));
	$("ssid").value = "Hidden network";
	$("wifiPassword").value = "my password";
	await wifiDiscovery($).open();
	assert.equal(calls, 3);
	assert.equal($("ssid").value, "Hidden network");
	assert.equal($("wifiPassword").value, "my password");
});

test("an empty scan stops polling and leaves manual entry available", async (t) => {
	const $ = controls(t);
	t.mock.method(globalThis, "setTimeout", (callback) => { queueMicrotask(callback); return 0; });
	t.mock.method(globalThis, "fetch", async () => ({ ok: true, json: async () => ({ networks: [] }) }));
	await wifiDiscovery($).open();
	assert.equal(globalThis.fetch.mock.callCount(), 12);
	assert.equal($("wifiNetworkLabel").hidden, true);
	assert.match($("wifiScanStatus").textContent, /No networks found/);
	assert.equal($("scanWifi").disabled, false);
});

test("scan failures show an error and allow retry", async (t) => {
	const $ = controls(t);
	t.mock.method(globalThis, "fetch", async () => ({ ok: false }));
	await wifiDiscovery($).open();
	assert.match($("wifiScanStatus").textContent, /search failed/);
	assert.equal($("scanWifi").disabled, false);
	await $("scanWifi").onclick();
	assert.equal(globalThis.fetch.mock.callCount(), 2);
});
